int ways(int coins[], int count, int amount)
{
    // Base case: exact amount achieved.
    if (amount == 0)
        return 1;

    // No more coins or insufficient remaining amount.
    if (amount < 0 || count == 0)
        return 0;

    // Recursive case: either exclude the current coin or include it.
    return ways(coins, count - 1, amount) + ways(coins, count, amount - coins[count - 1]);
}

