int choose(int n, int k)
{
    // Memoization table: dp[i][j] stores the number of ways to choose j elements from i
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, 0));

    // Helper lambda to compute choose with memoization
    auto dp_choose = [&](int i, int j) -> int {
        if (j == 0 || j == i)
            return 1;
        if (dp[i][j] != 0)
            return dp[i][j];
        dp[i][j] = dp_choose(i - 1, j - 1) + dp_choose(i - 1, j);
        return dp[i][j];
    };

    return dp_choose(n, k);
}

