        return -1;

    // Use the standard library algorithm for clarity and potential optimizations.
    auto it = std::lower_bound(table + low, table + high + 1, wanted);
    if (it != table + high + 1 && *it == wanted)
        return static_cast<int>(it - table);
    else
        return -1;
}

