int search(const int* table, int low, int high, int wanted)
{
    // Guard against an empty table; no element can be found.
    if (!table || low > high)
        return -1;

    // Binary search using the standard midpoint formula.
    const int mid = low + (high - low) / 2;

    // Compare the target with the middle element.
    if (table[mid] == wanted)
        return mid;

    // If the target is larger, search the right half.
    if (table[mid] < wanted)
        return search(table, mid + 1, high, wanted);

    // Otherwise, search the left half.
    return search(table, low, mid - 1, wanted);
}

int search(const int* table, int low, int high, int wanted)
{
    // Guard against an empty table; no element can be found.
    if (table == nullptr || low > high)
        return -1;

    // Binary search loop using the standard midpoint formula.
    while (low <= high) {
        const int mid = low + (high - low) / 2; // avoid overflow
        if (table[mid] == wanted)
            return mid; // element found
        if (table[mid] < wanted)
            low = mid + 1; // search right half
        else
            high = mid - 1; // search left half
    }
    return -1; // element not present
}

