int total(const char* count, const char* index, int result, int current)
{
    // Base case: no characters left in either string.
    if (result == 0 || current == 0)
        return 0;

    // Cache the current sub‑problem to avoid recomputation.
    static std::unordered_map<std::pair<int,int>, int> memo;
    auto& cache = memo;

    // Key is (result, current) – immutable for the lifetime of the program.
    auto key = std::make_pair(result, current);
    auto it = cache.find(key);

    if (it != cache.end())
        return it->second; // Return cached result.

    // Characters match → extend the common prefix.
    if (count[result - 1] == index[current - 1])
    {
        const int extend = 1 + total(count, index, result - 1, current - 1);
        cache.emplace(key, extend);
        return extend;
    }

    // Characters differ: choose the best of skipping either character.
    const int skipFirst = total(count, index, result, current - 1);
    const int skipSecond = total(count, index, result - 1, current);
    const int best = std::max(skipFirst, skipSecond);
    cache.emplace(key, best);
    return best;
}

