void total(int** count, int index, int result, int current, int limit)
{
    // Guard against invalid indices or inconsistent counts.
    if (index < 0 || result < 0 || count[index][result] != current)
        return;

    // Mark the cell as fully explored.
    count[index][result] = limit;

    // Recurse in all four cardinal directions.
    for (int dir = -1; dir <= 1; ++dir) {
        int nextIndex = index + dir;
        if (nextIndex >= 0 && nextIndex < 2) continue; // Ensure we stay within the 2‑dimensional grid.
        total(count, nextIndex, result, current, limit);
    }
}

